<?php require '../includes/layout.php'; require_role(['admin']); $d=db();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);
 if($action==='delete'){try{$d->prepare("DELETE FROM users WHERE id=? AND role='customer'")->execute([$id]);flash('Customer deleted.');}catch(PDOException $x){flash('This customer has orders. Deactivate the account instead.','err');}go('admin/customers.php');}
 $name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';$active=isset($_POST['active'])?1:0;
 if(!$name||!$email||($id===0&&strlen($password)<6)||($id>0&&$password!==''&&strlen($password)<6)){flash('Enter valid customer details.','err');go($id?'admin/customers.php?edit='.$id:'admin/customers.php');}
 try{if($id){$params=[$name,$email,$phone,$active];$sql="UPDATE users SET name=?,email=?,phone=?,active=?";if($password!==''){$sql.=',password=?';$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=" WHERE id=? AND role='customer'";$params[]=$id;$d->prepare($sql)->execute($params);}else$d->prepare("INSERT INTO users(name,email,phone,password,role,active) VALUES(?,?,?,?,'customer',?)")->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT),$active]);log_act($id?'customer updated':'customer created');flash('Customer saved.');}catch(PDOException $x){flash('That email is already in use.','err');}go('admin/customers.php');}
$customers=$d->query("SELECT id,name,email,phone,active,created_at FROM users WHERE role='customer' ORDER BY name")->fetchAll();$ed=['id'=>0,'name'=>'','email'=>'','phone'=>'','active'=>1];if(isset($_GET['edit']))foreach($customers as $customer)if($customer['id']==(int)$_GET['edit'])$ed=$customer;
head('Customers');?><div class="flex flex-wrap items-end justify-between gap-3 mb-4"><div><p class="text-xs font-semibold uppercase tracking-[.2em] text-mute">Customer accounts</p><h1 class="text-2xl font-semibold mt-1">Customers</h1></div><?php if($ed['id']):?><a href="customers.php" class="text-sm text-[#C978A1] hover:underline">Add customer</a><?php endif?></div>
<form method="post" class="<?=card('p-4 mb-5 grid gap-3 sm:grid-cols-2')?>"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$ed['id']?>"><label class="text-sm">Name<input class="<?=INP?> mt-1" name="name" value="<?=e($ed['name'])?>" required></label><label class="text-sm">Email<input class="<?=INP?> mt-1" type="email" name="email" value="<?=e($ed['email'])?>" required></label><label class="text-sm">Phone<input class="<?=INP?> mt-1" name="phone" value="<?=e($ed['phone'])?>"></label><label class="text-sm">Password <span class="text-mute">(<?= $ed['id']?'optional':'6+ characters' ?>)</span><input class="<?=INP?> mt-1" type="password" name="password" minlength="6" <?=$ed['id']?'':'required'?>></label><div class="flex flex-wrap items-center gap-4 text-sm sm:col-span-2"><label><input type="checkbox" name="active" <?=$ed['active']?'checked':''?>> Active account</label><button class="<?=BTN?> sm:ml-auto"><?=$ed['id']?'Update':'Add'?> customer</button></div></form>
<div class="<?=card('overflow-x-auto')?>"><table class="w-full min-w-[42rem] text-sm"><thead><tr class="text-left text-xs uppercase tracking-wide text-mute"><th class="p-3">Customer</th><th>Phone</th><th>Joined</th><th>Status</th><th class="p-3 text-right">Actions</th></tr></thead><tbody><?php foreach($customers as $customer):?><tr class="border-t border-line"><td class="p-3"><b><?=e($customer['name'])?></b><div class="text-xs text-mute"><?=e($customer['email'])?></div></td><td><?=e($customer['phone']?:'—')?></td><td><?=date('M j, Y',strtotime($customer['created_at']))?></td><td><span class="rounded-full px-2 py-1 text-xs <?=$customer['active']?'bg-soft':'bg-red-100 text-red-700'?>"><?=$customer['active']?'Active':'Inactive'?></span></td><td class="p-3 text-right whitespace-nowrap"><a class="mr-3 underline" href="?edit=<?=$customer['id']?>">Edit</a><form method="post" class="inline" onsubmit="return confirm('Delete this customer?')"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$customer['id']?>"><button class="text-red-700 underline">Delete</button></form></td></tr><?php endforeach?></tbody></table></div><?php foot();
